from author_helpers import Draft
b=Draft(31)
b.concept('temporal_property','Temporal property Rule','GTL Rule(kind=temporal_property) with formula, consequence class, gate point and identity as Rule.config data; dynamic authoring-loop enforcement over ABG replay, not a new structural type, rule surface or property carrier.',[(0,6,16)])
