b.concept('mapping_domain','GTL-to-runtime bridge law','Requirement domain for capability translation, GTL/runtime mapping and bridge provenance between constitutional declarations and ABG realization.',[(2,3,5),(3,9,11)])
b.concept('tenant_manifest','Tenant conformance manifest','Versioned engine/build-tenant declaration of validated/traversed GTL constructs and realized public capability contracts, bound to exact public contract/capability identities.',[(6,14,16),(7,20,28)])
b.concept('engine_mapping','Engine mapping contract','Language-preserving mapping of GTL Programs to canonical ABG engine surfaces with permissible alternate engine mappings.',[(9,14,14),(10,18,22)])
b.concept('authority_mapping','GTL HoG ABG authority mapping','Lossless path from authored GTL through non-lowering validation and direct HoG traversal to ABG runtime truth; workspace, adapters, compiler projections, bindings and helpers cannot become rival Programs/executors.',[(12,12,15)])
b.concept('gtl_program','GTL program','Graph composition owning topology, starts, callable membership, Roles, compute, policies, effects/results, proofs and publication metadata; distinct from GraphFunction, materialized Graph, workspace, HoG invocation and runtime episode.',[(13,19,28)])
b.concept('workspace','Workspace','Mutable instance surface for files, data, config, observations, generated artifacts and archives, without Program, callable-selection, traversal-state, closure or controller authority.',[(13,19,23),(13,30,33)])
b.concept('graph_function','GraphFunction','Sole named callable work contract within admitted Program/catalog membership, reusable/bindable/composable/substitutable/refinable, not the whole Product Program.',[(13,19,23),(13,62,65)])
b.constraint('temporal_replay_atom_domain',['temporal_property'],'Atoms quantify only over admitted replay: event occurrence by admitted kind with optional field-equality guards, or fluent hold from RUNTIME_FLUENT_NAME_VALUES via the single runtime Event Calculus. No node/workspace state, Worker shape or nonreplay surface quantification. New propositions extend the one fluent vocabulary with Event Calculus axioms, never a second vocabulary.',[(0,18,26)])
b.constraint('temporal_closed_grammar',['temporal_property'],'Allowed operators are not/and/or/implies, yesterday/once/historically/since, and next/eventually/globally/until. Unknown operators/atoms or malformed formula fail admission closed with a typed issue, never vacuous satisfaction.',[(0,28,33)])
b.constraint('finite_trace_three_valued_law',['temporal_verdict'],'Past-time formulas are stepwise decidable at every step. Undecided future obligations on finite traces are undetermined, neither satisfied nor violated; end-of-trace default satisfaction is forbidden. Implication properties count antecedent witnesses; zero witnesses marks vacuity and cannot count as satisfied for gate, closure, release or downstream interpretation.',[(0,35,46)])
b.constraint('temporal_consequence_classes',['temporal_property','temporal_verdict'],'Every property declares consequence class. safety_gate is past-time decidable and may block online at its declared point; a violated safety may not silently pass. liveness_residual never blocks; violated and undetermined results become pressure through existing residual carriers. A blocking liveness verdict is unlawful.',[(0,48,54)])
b.constraint('temporal_gate_points',['temporal_property'],'Closed gate vocabulary is dispatch and closure. Dispatch evaluates prefix before the F_P arm and a violated safety property blocks with typed reason. Closure evaluates at edge close and violation contributes no-close pressure. Blocking is replay-visible and names property and implicated refs.',[(0,56,61)])
b.constraint('temporal_verdict_nonauthority',['temporal_verdict'],'Emit canonical-path verdict events with property/formula/status/vacuity/witness/implicated-event/evaluation/replay fields. Verdicts are projections over admitted events that read/report residual, continuation, coverage and closure surfaces; they cannot re-derive or write that truth.',[(0,63,69)])
b.constraint('temporal_ingress_transition',['temporal_property'],'Author properties in GTL Module.rules. Current ingress is one engine-start passthrough authority forwarded by every public seam until execution-basis-carried Module rules become the named successor. No second side door. Startup property-set admission fails closed on malformed grammar/atoms.',[(0,71,76)],conditions=['Engine-start passthrough remains ingress until the named basis-carried successor.'])
b.constraint('temporal_proof_before_enforcement',['temporal_property'],'Standing first properties cover dispatch-manifest lineage, closure-coverage on declared carry-through edges, no Worker call without startup, no coverage from rejected payloads and selection-authority. Gate enforcement follows mutation differential (trace edit flips satisfied to violated) and vacuity differential (witness removal is vacuous, not satisfied); liveness_residual additionally requires an undetermined-routing differential with no block and residual pressure.',[(0,78,86)])
b.constraint('temporal_total_checker',['temporal_property','temporal_verdict'],'Checker is total deterministic over finite replay trace plus declared properties, consuming the one Event Calculus projection for fluents. Checker error becomes blocked evaluation with typed reason, never silent skip. Temporal properties read no clocks and preserve T-119 scheduling typed-exempt disposition pending timer-provider seam.',[(0,88,97)])
b.constraint('uniform_envelope_temporal_amendment',['temporal_property'],'Dispatch gate on the uniform C-call envelope binds c_call_fibre_selected with single-event where guards under CCALL-010, requiring/implying no cross-event join. fp_dispatch_requested antecedent remains lawful only for pre-envelope replay through the CCALL-011 projection adapter.',[(1,101,104)],conditions=['Use c_call_fibre_selected for the uniform C-call envelope.'],exceptions=['Pre-envelope replay may use fp_dispatch_requested through the named adapter.'])
b.relation('property_yields_verdict','checked_as','temporal_property','temporal_verdict','A declared property is deterministically evaluated over finite replay into a typed, provenance-preserving verdict without acquiring runtime authority.',[(0,6,8),(0,63,69),(0,88,92)],False)
b.constraint('manifest_exact_basis',['tenant_manifest'],'Align with active GTL/ABG/mapping requirements and exact public identities projected from one accepted capability-definition graph, never source path, language, private design identity or tenant capability vocabulary. Manifest carries schema version, identity/version/digest, engine identity/version, exact accepted graph identity/digest and realized public capability/contract identities.',[(7,20,26)])
b.constraint('manifest_support_contracts',['tenant_manifest'],'Identify supported GTL Program/declaration/GraphFunction publication, ABG event/result/replay, catalog/installed-Product, derived public functions and Worker effect/result capability contracts. Support rows project accepted definition graph/public catalog and redefine neither. Each row names stable capability identity, owning graph row, owning public contract identity/version/digest, supported disposition and required dependency identities. Derive rows from accepted graph/catalog without source/design history.',[(7,28,28),(7,62,77)])
b.constraint('conformance_claim_scope',['tenant_manifest'],'Bind every claim to exact manifest identity/version/digest and exact graph/public-catalog basis, both authorities bound by identity/version/digest and resolved through installed publicContractCatalog under PUBLIC-CONTRACTS. Claim only listed realized identities. Package presence, unversioned feature names, unrelated tests, duplicate local definitions, requirement prose, private export scans or separate capability enums prove no conformance.',[(7,30,30),(7,62,77)])
b.constraint('conformance_failure_and_evolution',['tenant_manifest'],'Match callable effects against engine profiles for dispatch. Incompatible/unresolved contract, capability, manifest dependency or declared effect is an explicit conformance gap and fails closed before affected execution admission. Changed published meaning requires a new versioned manifest claim; replay/qualification preserves exact execution manifest identity/digest.',[(7,24,24),(7,32,34)])
b.constraint('manifest_non_control_plane',['tenant_manifest'],'Manifest is declaration/read-model evidence consumable by conformance/admission/runtime/qualification. It creates no second validator, HoG traversal authority, ABG truth authority, release checker, tenant control plane or capability-definition authority.',[(7,36,36),(7,74,77)])
b.constraint('carrier_class_predecessor_law',['tenant_manifest'],'Published enforcement contract classifies carriers as root/declaration, causal, derived, transition or closure-bearing before predecessor/behavior checks, never from filenames/tests. For the latter classes, when their declared contract requires an admitted causal predecessor, absence, incompatibility or nontraceable identity fails conformance. Root/declaration carriers are not rejected merely for lawfully starting a chain.',[(7,38,48)],conditions=['Predecessor enforcement applies where the carrier contract requires one.'],exceptions=['Lawful root/declaration starts do not require a fictitious predecessor.'])
b.constraint('behavioral_determinism_boundary',['tenant_manifest'],'Reject F_D implementation behavior doing semantic quality, intent satisfaction, acceptance, open-domain or other nontotal judgment instead of HANDLERS-permitted mechanical total finite-state predicates. Merely declaring an F_D contract in a root declaration is not behavioral execution and is not rejected on that ground.',[(7,50,55)],exceptions=['A root declaration describing F_D is not behavioral F_D execution.'])
b.constraint('bounded_enforcement_proof',['tenant_manifest'],'Proof includes positive root/declaration fixtures and negative missing-predecessor and behavioral-F_D fixtures. Exact-candidate release manifest cites the owning proof rather than duplicating rules in a release-local checker.',[(7,57,60)])
b.latitude('engine_target_variation',['engine_mapping'],['Map alternate engines such as Temporal, Prefect or Step Functions fully, partially or by capability profile.','Expose selected-subgraph/evaluator companion bundles if traceable to the published callable and Graph stays primary language truth.'],['Letting engine-specific behavior change GTL semantics.','Replacing Graph truth with companion bundles.'],[(10,18,26)])
b.constraint('mapping_materialization_and_proof',['engine_mapping'],'When Programs publish GraphFunctions, canonical mapping specifies their executable-graph materialization before execution/evaluation binding. When a refined/realized callable declares deterministic proof surfaces, derive the evaluator bundle from the same materialization/refinement truth.',[(10,24,28)],conditions=['GraphFunctions are published by the Program.','Evaluator derivation applies where the boundary declares deterministic proof surfaces.'])
b.constraint('graph_frame_semantic_conservation',['engine_mapping'],'Authoring/publication/serialization/execution conserve Product graph/frame calculus. For identical bound observations and admitted evaluator outputs, conserve permitted choices, effects, refusals and completion conditions, including nested calls/parent obligations. Structure alone establishes neither semantic adequacy nor identical repeated F_P judgments. Frame meaning stays with its owner; encoding adds no controller or deterministic undeclared semantic-policy interpretation.',[(10,30,37)],conditions=['Comparison uses the same bound observations and admitted evaluator outputs.'])
b.constraint('program_workspace_nonruntime_truth',['gtl_program','workspace','graph_function'],'Keep Program, callable, materialized Graph, workspace, HoG invocation and ABG episode distinct. Program owns declared topology/start/membership/Role/compute/policy/effect/result/proof/publication; authoring emits no events or runtime truth. Workspace supplies mutable instance state and never Program authority, callable-selection/traversal/closure truth or control.',[(13,19,33)])
b.constraint('public_invocation_exact_binding',['authority_mapping','graph_function'],'Before entry bind exact Product, install, workspace, catalog view, admitted Program, callable membership, contracts and invocation authority. Public starts/calls enter installed public admission. CLI/SDK/workspace/fixture/plugin/direct-vector paths cannot select private Programs, Workers, topology or execution basis.',[(13,35,37),(13,72,75)])
b.constraint('nonlowering_traversal_path',['authority_mapping'],'TypeScript and validator judge local/whole-Program law before effects. Canonical serialization, diagnostics, normalized indexes and unresolved pressure are subordinate outputs, never traversal input independent of admitted GTL. HoG directly traverses original GTL/materialized graphs with no generated HoG Program, CompiledCProgramPlan, compiled declaration, runtime catalog or executable IR.',[(13,39,49)])
b.constraint('effect_boundary_and_runtime_custody',['authority_mapping'],'F_D/F_P/F_H/Worker/tool/process execution remains inside declared boundaries; effect code owns no topology, traversal bind, admission, continuation or closure. ABG preserves at least exact Program, callable, materialized Graph, graph call, locus, frame/span lineage, workspace, compute regime, effect invocation, result/evidence admission, consequence, judgment, continuation and replay projection.',[(13,51,60)])
b.constraint('projection_and_extension_limits',['authority_mapping'],'Slot/lifecycle maps, catalogs, dashboards, parity matrices, validator indexes and caches are derived unless independently admitted by their owning authority; they select no traversal or Program state. Downstream may publish Modules/Programs/callables/types/contracts/bindings through common catalog law, never a parallel executor, registry, event writer, continuation model or closure ledger.',[(13,67,70),(13,77,80)],exceptions=['Independent admission by the owning authority may give a projection a separate standing; mere presence does not.'])
b.constraint('owned_joins_and_execution_proof',['authority_mapping'],'Design/realization identify owners and truth sources at declaration, validation, admission, traversal, effect, event admission, replay, continuation and projection joins; an unowned join is a typed design gap. Execution proof enters an admitted Program start/callable and cites ABG replay for every traversal-affecting result. Direct vectors/plugins/Workers/fixtures are not parity proof.',[(13,82,90)])
b.constraint('installed_context_drift_checks',['authority_mapping'],'Installed context/bootloader projections bind selected Product/method identities and check stale assignments of Program/traversal/closure authority to callables, workspaces, adapters or ABG-as-executor. Validator/context checks report/reject drift only; they cannot write instructions, mutate binding, install Products, select Program, emit events or replace Product materialization.',[(13,92,100)])
b.relation('callable_member_of_program','requires_membership_in','graph_function','gtl_program','Callable reuse and execution require admitted Program and catalog membership; callable is not relabeled as the whole Program.',[(13,62,65)],True)
